### Ex) 적분 함수
```typescript
const integralObject = (original: any, delta: any) => {
    if (typeof original !== 'object' || original === null) {
        return delta; // 원시형 데이터라면 새로운 값으로 대체
    }

    if (Array.isArray(original) && Array.isArray(delta)) {
        return [...original, ...delta]; // 배열이라면 변화량을 뒤에 붙힘(TLRecord의 update에 따른 로직)
    }

    // 객체일 경우
    if (typeof original === 'object' && typeof delta === 'object') {
        const newObject = { ...original };
        for (const key in delta) {
            if (delta.hasOwnProperty(key)) { // 주의: prototype
                // 재귀
                newObject[key] = integralObject(original[key], delta[key]);
            }
        }
        return newObject;
    }

    return delta;
};

```
### Ex) 미분
```typescript
const differentialObject = (prev: any, next: any): any => {
    if (typeof prev !== 'object' || prev === null) {
        return next;
    }

    if (Array.isArray(prev) && Array.isArray(next)) {
        return next.slice(prev.length); // next는 prev의 원소를 모두 앞에 포함
        // 즉 [1,2,3]이라면 [2,2,4]인 경우는 존재하지 않음
    }

    // 객체일 경우 객체의 차이를 반환
    if (typeof prev === 'object' && typeof next === 'object') {
        const difference: any = {};
        for (const key in next) {
            if (next.hasOwnProperty(key)) {
                if (!(key in prev)) {
                    difference[key] = next[key]; // 새로운 key
                } else {
                    const diff = differentialObject(prev[key], next[key]);
                    if (typeof diff !== 'undefined') {
                        difference[key] = diff; // 차이가 존재하는 경우 갱신
                    }
                }
            }
        }
        // undefined는 차이 없음을 의미
        // key가 존재해야 차이가 존재
        return Object.keys(difference).length > 0 ? difference : undefined; 
    }

    // undefined는 차이 없음을 의미
    return undefined;
};
```

